modules.model.cod:
type Entity;
type Weighted <: Entity;
type Alternate <: Entity;
data Node { value::i64; next::ref<Node>; }
function rank(x::Entity)::i64 { 1 }
function rank(x::Weighted)::i64 { 2 }
export Entity; export Weighted; export Alternate; export Node; export rank;

modules.weighted.cod:
export import "model.cod" Node;
using "model.cod" Weighted;
data Node <: Weighted;
function create(arena::region)::Weighted {
 let tail = alloc arena Node(30, null);
 let middle = alloc arena Node(20, tail);
 deref(alloc arena Node(10, middle))
}
export create;

modules.alternate.cod:
export import "model.cod" Node;
using "model.cod" Alternate;
data Node <: Alternate;
function create(arena::region)::Alternate { deref(alloc arena Node(90, null)) }
export create;

modules.helpers.cod:
using "model.cod" Entity;
using "model.cod" rank;
using "weighted.cod" create as left;
using "alternate.cod" create as right;
function choose(arena::region, choice::bool)::Entity {
 if (choice) { left(arena) } else { right(arena) }
}
function reverse(arena::region, choice::bool)::Entity {
 if (choice) { right(arena) } else { left(arena) }
}
function walk(node::Entity, steps::u32)::Entity {
 fold (i in 0u32 .. steps, current = node) {
  if (current.next == null) { current } else { deref(current.next) }
 }
}
function score_choice(arena::region, choice::bool)::i64 { rank(choose(arena, choice)) }
function score_walk(node::Entity, steps::u32)::i64 { rank(walk(node, steps)) }
export choose; export reverse; export walk; export score_choice; export score_walk;

