using symbol "std:io" @print;
symbol @arena::region;
effect @arena <- region(16384u64);
using "helpers.cod" choose;
using "helpers.cod" reverse;
using "helpers.cod" walk;
using "helpers.cod" score_choice as frozen_choice;
using "helpers.cod" score_walk as frozen_walk;
using "adapted.cod" score_choice as adapted_choice;
using "adapted.cod" score_walk as adapted_walk;
using "weighted.cod" create;
behave @print(choose(@arena, true).value);
behave @print(choose(@arena, false).value);
behave @print(reverse(@arena, true).value);
behave @print(reverse(@arena, false).value);
behave @print(frozen_choice(@arena, true));
behave @print(frozen_choice(@arena, false));
behave @print(adapted_choice(@arena, true));
behave @print(adapted_choice(@arena, false));
{
 let node = create(@arena);
 behave @print(walk(node, 0u32).value);
 behave @print(walk(node, 1u32).value);
 behave @print(walk(node, 2u32).value);
 behave @print(walk(node, 9u32).value);
 behave @print(frozen_walk(node, 3u32));
 behave @print(adapted_walk(node, 1u32));
 let tail = walk(node, 3u32);
 setfield(tail, value, 71);
 behave @print(adapted_walk(node, 3u32));
};

